type TypedCommands<TCommands> = {
    [TName in keyof TCommands]: TCommands[TName] extends (
        ...args: infer TArgs
    ) => Promise<infer TResult>
        ? (...args: TArgs) => CommandPromise<TResult>
        : TCommands[TName];
};

export const commands: TypedCommands<typeof generatedCommands> =
    generatedCommands;

